-- The finale's twelve joins between June's records, and how often each pair agrees. Eight always
-- agree: one record is written from the other. Four sometimes disagree: one side looks at the world.
select 'picks-notice' as join_id, 'picks' as record_a, 'notice' as record_b, compared, agree from (SELECT count(*) AS compared, sum(CASE WHEN p.sku = n.sku AND p.cases_confirmed = n.cases THEN 1 ELSE 0 END) AS agree FROM {{ ref('picks') }} p JOIN {{ ref('notice_lines') }} n USING (shipment_id, line))
union all
select 'notice-labels' as join_id, 'notice' as record_a, 'labels' as record_b, compared, agree from (SELECT count(*) AS compared, sum(CASE WHEN n.cases = p.cases THEN 1 ELSE 0 END) AS agree FROM (SELECT sscc, sum(cases) AS cases FROM {{ ref('notice_lines') }} GROUP BY sscc) n JOIN {{ ref('pallets') }} p USING (sscc))
union all
select 'notice-receipts' as join_id, 'notice' as record_a, 'receipts' as record_b, compared, agree from (SELECT count(*) AS compared, sum(CASE WHEN r.sku_booked = n.sku AND r.units_booked = n.units THEN 1 ELSE 0 END) AS agree FROM {{ ref('goods_receipts') }} r JOIN {{ ref('notice_lines') }} n ON r.shipment_id = n.shipment_id AND r.line = n.line)
union all
select 'receipts-counts' as join_id, 'receipts' as record_a, 'counts' as record_b, compared, agree from (WITH pairs AS (SELECT c.count_ts, c.sku, c.adjustment, r.units_booked, row_number() OVER (PARTITION BY c.count_ts, c.sku ORDER BY r.received_ts DESC) AS k FROM {{ ref('stock_counts') }} c JOIN {{ ref('goods_receipts') }} r ON r.sku_booked = c.sku AND r.received_ts < c.count_ts) SELECT count(*) AS compared, sum(CASE WHEN adjustment > -0.5 * units_booked THEN 1 ELSE 0 END) AS agree FROM pairs WHERE k = 1)
union all
select 'book-ledger' as join_id, 'book' as record_a, 'lines' as record_b, compared, agree from (WITH inflow AS (SELECT CAST(received_ts AS DATE) AS date, sku_booked AS sku, sum(units_booked) AS u FROM {{ ref('goods_receipts') }} GROUP BY ALL UNION ALL SELECT CAST(delivery_ts AS DATE), sku, sum(units) FROM {{ ref('fresh_deliveries') }} GROUP BY ALL), adj AS (SELECT CAST(count_ts AS DATE) AS date, sku, sum(adjustment) AS a FROM {{ ref('stock_counts') }} WHERE strftime(count_ts, '%H:%M') < '22:00' GROUP BY ALL UNION ALL SELECT CAST(count_ts AS DATE) + 1, sku, sum(adjustment) FROM {{ ref('stock_counts') }} WHERE strftime(count_ts, '%H:%M') >= '22:00' GROUP BY ALL), d AS (SELECT b.date, b.sku, b.book_on_hand_close AS book, lag(b.book_on_hand_close) OVER (PARTITION BY b.sku ORDER BY b.date) AS prev, coalesce((SELECT sum(u) FROM inflow i WHERE i.date = b.date AND i.sku = b.sku), 0) AS inflow, coalesce((SELECT sum(units_sold) FROM {{ ref('daily_sales') }} s WHERE s.date = b.date AND s.sku = b.sku), 0) AS sold, coalesce((SELECT sum(units) FROM {{ ref('write_offs') }} w WHERE w.date = b.date AND w.sku = b.sku), 0) AS written_off, coalesce((SELECT sum(a) FROM adj WHERE adj.date = b.date AND adj.sku = b.sku), 0) AS counted FROM {{ ref('inventory_book') }} b) SELECT count(*) AS compared, sum(CASE WHEN book = prev + inflow - sold - written_off + counted THEN 1 ELSE 0 END) AS agree FROM d WHERE prev IS NOT NULL)
union all
select 'book-counts' as join_id, 'book' as record_a, 'counts' as record_b, compared, agree from (SELECT count(*) AS compared, sum(CASE WHEN adjustment = 0 THEN 1 ELSE 0 END) AS agree FROM {{ ref('stock_counts') }})
union all
select 'book-audits' as join_id, 'book' as record_a, 'audits' as record_b, compared, agree from (WITH a AS (SELECT audit_ts, sku, status, CAST(audit_ts AS DATE) AS date FROM {{ ref('shelf_audits') }}), b AS (SELECT a.*, coalesce((SELECT book_on_hand_close FROM {{ ref('inventory_book') }} k WHERE k.sku = a.sku AND k.date = a.date - 1), 0) + coalesce((SELECT sum(units_booked) FROM {{ ref('goods_receipts') }} r WHERE r.sku_booked = a.sku AND CAST(r.received_ts AS DATE) = a.date AND r.received_ts <= a.audit_ts), 0) + coalesce((SELECT sum(units) FROM {{ ref('fresh_deliveries') }} f WHERE f.sku = a.sku AND CAST(f.delivery_ts AS DATE) = a.date AND f.delivery_ts <= a.audit_ts), 0) - coalesce((SELECT sum(qty) FROM {{ ref('pos_lines') }} l WHERE l.sku_scanned = a.sku AND CAST(l.bill_ts AS DATE) = a.date AND l.bill_ts <= a.audit_ts), 0) + coalesce((SELECT sum(adjustment) FROM {{ ref('stock_counts') }} c WHERE c.sku = a.sku AND CAST(c.count_ts AS DATE) = a.date AND c.count_ts <= a.audit_ts), 0) AS book_at_audit FROM a) SELECT count(*) AS compared, sum(CASE WHEN (status = 'empty') = (book_at_audit <= 0) THEN 1 ELSE 0 END) AS agree FROM b)
union all
select 'lines-payments' as join_id, 'lines' as record_a, 'payments' as record_b, compared, agree from (SELECT count(*) AS compared, sum(CASE WHEN approved = 1 THEN 1 ELSE 0 END) AS agree FROM (SELECT l.bill_id, (SELECT count(*) FROM {{ ref('till_payments') }} p WHERE p.bill_id = l.bill_id AND p.till_status = 'approved') AS approved FROM (SELECT DISTINCT bill_id FROM {{ ref('pos_lines') }} WHERE bill_ts >= '2026-06-01') l))
union all
select 'payments-provider' as join_id, 'payments' as record_a, 'provider' as record_b, compared, agree from (SELECT count(*) AS compared, sum(CASE WHEN p.status = 'success' AND p.amount_inr = t.amount_inr THEN 1 ELSE 0 END) AS agree FROM {{ ref('till_payments') }} t LEFT JOIN {{ ref('psp_upi') }} p USING (rrn) WHERE t.tender = 'UPI' AND t.till_status = 'approved')
union all
select 'timeouts-provider' as join_id, 'payments' as record_a, 'provider' as record_b, compared, agree from (select count(*) as compared, sum(case when outcome = 'never debited' then 1 else 0 end) as agree from {{ ref('timeouts_matched') }})
union all
select 'provider-settlements' as join_id, 'provider' as record_a, 'settlements' as record_b, compared, agree from (WITH s AS (SELECT CAST(status_ts AS DATE) + 1 AS settlement_date, count(*) AS credits, round(sum(amount_inr), 2) AS gross FROM {{ ref('psp_upi') }} WHERE status = 'success' GROUP BY ALL) SELECT count(*) AS compared, sum(CASE WHEN x.upi_credits = coalesce(s.credits, 0) AND abs(x.gross_inr - coalesce(s.gross, 0)) <= 0.01 THEN 1 ELSE 0 END) AS agree FROM {{ ref('settlements') }} x LEFT JOIN s USING (settlement_date))
union all
select 'provider-refunds' as join_id, 'provider' as record_a, 'refunds' as record_b, compared, agree from (SELECT count(*) AS compared, sum(CASE WHEN p.status = 'success' AND p.amount_inr = r.amount_inr THEN 1 ELSE 0 END) AS agree FROM {{ ref('refunds') }} r LEFT JOIN {{ ref('psp_upi') }} p USING (rrn))
